/* Original MigBits theme. MIT; preserve LICENSE.txt. Fonts are separate OFL resources. */

:root {
  --background: #f8fafc;
  --foreground: #0f172a;
  --card: #ffffff;
  --card-foreground: #0f172a;
  --popover: #ffffff;
  --popover-foreground: #0f172a;
  --primary: #115e59;
  --primary-foreground: #ffffff;
  --secondary: #e2e8f0;
  --secondary-foreground: #0f172a;
  --muted: #f1f5f9;
  --muted-foreground: #475569;
  --accent: #e2e8f0;
  --accent-foreground: #0f172a;
  --destructive: #b91c1c;
  --destructive-foreground: #ffffff;
  --border: #64748b;
  --input: #64748b;
  --ring: #115e59;
  --radius: 1rem;
  --font-heading: "Space Grotesk", serif;
  --font-body: "DM Sans", sans-serif;
  --font-mono: "Geist Mono", monospace;
  --decorative-gradient: linear-gradient(125deg,#115e59,#a3e635);
}

.dark {
  --background: #0b1220;
  --foreground: #f1f5f9;
  --card: #111c30;
  --card-foreground: #f1f5f9;
  --popover: #111c30;
  --popover-foreground: #f1f5f9;
  --primary: #5eead4;
  --primary-foreground: #0b1220;
  --secondary: #1e293b;
  --secondary-foreground: #f1f5f9;
  --muted: #1e293b;
  --muted-foreground: #cbd5e1;
  --accent: #23314a;
  --accent-foreground: #f1f5f9;
  --destructive: #fca5a5;
  --destructive-foreground: #0b1220;
  --border: #64748b;
  --input: #64748b;
  --ring: #5eead4;
  --radius: 1rem;
  --font-heading: "Space Grotesk", serif;
  --font-body: "DM Sans", sans-serif;
  --font-mono: "Geist Mono", monospace;
  --decorative-gradient: linear-gradient(125deg,#115e59,#a3e635);
}

/* Tailwind v4 / shadcn: map these semantic variables in your existing @theme inline block. Keep text on semantic surfaces, not on the decorative gradient. */
